query MexFetchNewsletterFollowersJobQuery($input) {
  id
  display_name
  pn
  username
  follow_time
  role
  admin_profile {
    name
    picture {
      direct_path
      xwa2_newsletter_followers {
        followers {
          edges {
            node {
              username_info {
                xwa2_newsletter_followers {
                  followers {
                    edges {
                      node {
                        username_info {
                          __typename
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
